import unittest
from subject import route


class RouteTests(unittest.TestCase):
    # 判準來源：題目規格；expected 為依規格人工推導的字面值。

    def test_confirmed_examples(self):
        # 已確認例子
        self.assertEqual(route(0, True), "weekday")
        self.assertEqual(route(5, True), "weekend")

    def test_weekday_all_days_0_to_4(self):
        # 規格：enabled=True 且 day 0..4 -> weekday；含邊界 4（抓 >=4 誤判）
        for d in (0, 1, 2, 3, 4):
            self.assertEqual(route(d, True), "weekday", d)

    def test_weekend_days_5_and_6(self):
        # 規格：day 5..6 -> weekend；含上界 6（抓 ==5 或 >=6 誤判）
        self.assertEqual(route(5, True), "weekend")
        self.assertEqual(route(6, True), "weekend")

    def test_disabled_returns_paused_for_every_valid_day(self):
        # 規格：合法 day 且 enabled=False -> paused（抓忽略 enabled 的退化）
        for d in range(7):
            self.assertEqual(route(d, False), "paused", d)

    def test_invalid_day_out_of_range_rejected(self):
        # 規格：day 不在 0..6 -> ValueError("invalid-day")；邊界 -1、7
        for d in (-1, 7, 100):
            for en in (True, False):
                with self.assertRaisesRegex(ValueError, r"^invalid-day$"):
                    route(d, en)

    def test_invalid_day_string_rejected_before_enabled(self):
        # 規格：先驗 day；字串非整數 -> invalid-day，即使 enabled=False 也不得回 paused
        for en in (True, False):
            with self.assertRaisesRegex(ValueError, r"^invalid-day$"):
                route("1", en)
